// Generated by scripts/types.js from schemas/**/*.json. Do not edit; run: npm run types
//
// The types describe the shape only. Patterns, ranges, formats and the conditional rules of the schemas
// (e.g. "lat_e7 and lng_e7 are both set or both null") are checked by schema validation, not by these types.

// common/accuracy-dm.json

/**
 * Horizontal accuracy radius of a location fix in decimetres, rounded to an integer (12.5 m → 125). The upper bound keeps it within a signed 32-bit column.
 */
export type AccuracyDm = number;

// common/base64.json

/**
 * Non-empty binary value in standard base64 (RFC 4648 section 4: alphabet A-Z a-z 0-9 + /, '=' padding required, no line breaks, no URL-safe alphabet). Used for PIN hash and salt and the device secret.
 */
export type Base64 = string;

// common/error-code.json

/**
 * Machine-readable error code. Request level (HTTP status): unauthenticated (401), device_revoked (401), forbidden (403), not_found (404), conflict (409, e.g. PIN or tag already taken), validation_failed (422), rate_limited (429); any other client error is bad_request (with its own 4xx status, e.g. 405, 413), any server error server_error (5xx, e.g. 500, 503 during maintenance). Entry level, in the push response's rejected list: chain_gap, chain_fork, bad_hmac.
 */
export type ErrorCode =
  | "unauthenticated"
  | "device_revoked"
  | "forbidden"
  | "not_found"
  | "validation_failed"
  | "conflict"
  | "chain_gap"
  | "chain_fork"
  | "bad_hmac"
  | "rate_limited"
  | "bad_request"
  | "server_error";

// common/hash.json

/**
 * A 32-byte digest as 64 lowercase hexadecimal characters: a SHA-256 digest (media) or an HMAC-SHA256 tag (chain entry hash, prev_hash). The first chain entry's prev_hash is 64 '0' characters.
 */
export type Hash = string;

// common/lat-e7.json

/**
 * WGS 84 latitude in degrees multiplied by 10^7 and rounded to an integer (47.4979° → 474979000). Floating-point numbers are not allowed in hashed data.
 */
export type LatE7 = number;

// common/lng-e7.json

/**
 * WGS 84 longitude in degrees multiplied by 10^7 and rounded to an integer (19.0402° → 190402000). Floating-point numbers are not allowed in hashed data.
 */
export type LngE7 = number;

// common/local-time.json

/**
 * Time of day as HH:MM (24-hour, zero-padded) in the site's time zone, e.g. 20:00.
 */
export type LocalTime = string;

// common/pin.json

/**
 * Exactly 6 ASCII digits, a string (001234 is not 1234). Unique among the users of a site (pin/test-vectors.json: pin_pattern).
 */
export type Pin = string;

// common/server-time.json

/**
 * The server clock when the response was produced. Required in every API response, including error responses; the app uses it with its monotonic clock to estimate trusted time.
 */
export type ServerTime = Timestamp;

// common/timestamp.json

/**
 * ISO 8601 / RFC 3339 instant in UTC with exactly three fractional digits and a 'Z' suffix, e.g. 2026-10-27T20:00:00.000Z. No offsets, no leap seconds. The pattern fixes the textual form; 'format' additionally rejects impossible dates such as February 30.
 */
export type Timestamp = string;

// common/timezone.json

/**
 * IANA time zone name, e.g. Europe/Budapest. The server also checks that the zone exists.
 */
export type Timezone = string;

// common/uuid.json

/**
 * RFC 9562 UUID version 7 in canonical lowercase text form. Every primary key is a UUIDv7, because records are also created on devices while offline. Lowercase only: IDs are part of hashed chain entries, so their text form must be unique.
 */
export type Uuid = string;

// entities/checkpoint.json

/**
 * A point on a site identified by an NFC tag and/or a QR code. NFC checkpoints (nfc, nfc_dna) have a tag_uid, QR checkpoints a qr_payload; either kind may carry the other as a fallback. Location is integer-encoded (no floats); lat_e7 and lng_e7 are both set or both null, accuracy_dm only with a location. Every property is present; absent values are null.
 */
export interface Checkpoint {
  id: Uuid;
  site_id: Uuid;
  name: string;
  /**
   * What the guard has to check here (Hungarian).
   */
  instruction: string | null;
  tag_type: "nfc" | "nfc_dna" | "qr";
  /**
   * NFC tag UID: uppercase hex without separators, 4 to 10 bytes. Unique within a site.
   */
  tag_uid: string | null;
  /**
   * waypost:cp:<checkpoint id>:<16-character random code>. Globally unique.
   */
  qr_payload: string | null;
  lat_e7: LatE7 | null;
  lng_e7: LngE7 | null;
  accuracy_dm: AccuracyDm | null;
  photo_media_id: Uuid | null;
  active: boolean;
  created_at: Timestamp;
  /**
   * Last change; drives the pull cursor.
   */
  updated_at: Timestamp;
}

