// chain/entry.json

/**
 * The fields every chain entry has besides type and payload (chain/entry.json).
 */
export interface ChainEntryFields {
  id: Uuid;
  device_id: Uuid;
  /**
   * Position in the device's chain: 1, 2, 3, … without gaps.
   */
  seq: number;
  /**
   * Device wall clock when the entry was created.
   */
  device_time: Timestamp;
  /**
   * Monotonic clock (time since boot, including sleep) in milliseconds.
   */
  uptime_ms: number;
  boot_id: BootId;
  /**
   * GNSS time of the location fix (Android, GPS provider only).
   */
  gnss_time: Timestamp | null;
  /**
   * server_time of the last successful sync; null until the first sync.
   */
  ref_server_time: Timestamp | null;
  /**
   * uptime_ms when ref_server_time was received.
   */
  ref_uptime_ms: number | null;
  ref_boot_id: BootId | null;
  /**
   * hash of the previous entry; 64 zeros for seq 1.
   */
  prev_hash: Hash;
  hash: Hash;
}

/**
 * Type of a chain entry.
 */
export type ChainEntryType = "shift_started" | "shift_closed" | "round_opened" | "scan" | "incident" | "round_closed";

/**
 * Payload type of each chain entry type (the type → payload branches of chain/entry.json).
 */
export interface ChainPayloadMap {
  shift_started: ShiftStartedPayload;
  shift_closed: ShiftClosedPayload;
  round_opened: RoundOpenedPayload;
  scan: ScanPayload;
  incident: IncidentPayload;
  round_closed: RoundClosedPayload;
}

/**
 * A chain entry of the given type.
 */
export interface ChainEntryOf<T extends ChainEntryType> extends ChainEntryFields {
  type: T;
  /**
   * Type-specific data, see chain/payload-<type>.json.
   */
  payload: ChainPayloadMap[T];
}

/**
 * One entry of a device's hash chain, as stored on the device and sent in sync push. hash = lowercase hex of HMAC-SHA256(key = device secret, message = RFC 8785 canonical JSON of this object without the "hash" property). Every property is present, null values included; there are no floating-point numbers anywhere, and every integer is within ±(2^53 − 1). New entry types (e.g. sos in stage 2) are added as a new enum value, a new payload schema and a new branch below, in a minor version.
 *
 * Discriminated union on type: narrowing on entry.type narrows entry.payload.
 */
export type ChainEntry = { [T in ChainEntryType]: ChainEntryOf<T> }[ChainEntryType];

/**
 * A chain entry without hash: the object whose RFC 8785 canonical JSON is the HMAC input.
 */
export type UnsignedChainEntry = { [T in ChainEntryType]: Omit<ChainEntryOf<T>, "hash"> }[ChainEntryType];

/**
 * Opaque identifier of the current boot (from the waypost-clock module); changes on every restart.
 */
export type BootId = string;

// chain/payload-incident.json

/**
 * An incident reported by the guard (also created with category damaged_tag and scan_id for a manual scan). Part of the hashed chain entry: every property is present (null when absent) and there are no floating-point numbers.
 */
export interface IncidentPayload {
  incident_id: Uuid;
  shift_id: Uuid;
  category: "vandalism" | "open_door" | "water" | "intruder" | "damaged_tag" | "other";
  /**
   * Free text from the guard (Hungarian).
   */
  note: string | null;
  lat_e7: LatE7 | null;
  lng_e7: LngE7 | null;
  accuracy_dm: AccuracyDm | null;
  nearest_checkpoint_id: Uuid | null;
  /**
   * The manual scan this incident belongs to.
   */
  scan_id: Uuid | null;
  /**
   * Photos taken with the camera, each with the SHA-256 of the uploaded file, so a replaced photo is detected.
   *
   * @maxItems 5
   */
  media: {
    id: Uuid;
    sha256: Hash;
  }[];
}

// chain/payload-round_closed.json

/**
 * A round closed: completed (every checkpoint scanned), or at its deadline incomplete (some scans) or missed (none). Part of the hashed chain entry: every property is present (null when absent) and there are no floating-point numbers.
 */
export interface RoundClosedPayload {
  round_id: Uuid;
  status: "completed" | "incomplete" | "missed";
  finished_at: Timestamp;
}

// chain/payload-round_opened.json

/**
 * A scheduled round opened (status open). A missed time slot is opened later with its original scheduled_at. Part of the hashed chain entry: every property is present (null when absent) and there are no floating-point numbers.
 */
export interface RoundOpenedPayload {
  round_id: Uuid;
  shift_id: Uuid;
  route_version_id: Uuid;
  schedule_id: Uuid;
  scheduled_at: Timestamp;
  /**
   * Copied from the schedule; null = no limit.
   */
  time_limit_min: number | null;
}

// chain/payload-scan.json

/**
 * A checkpoint scan by NFC, QR or manual entry. App-set flags: manual (manual entry), out_of_order (fixed order, not the expected checkpoint), out_of_round (no open round or checkpoint not on the route; round_id is then null), unknown_tag (no checkpoint for the tag; checkpoint_id is then null), mock_location (Android mock location provider; equals is_mock). Part of the hashed chain entry: every property is present (null when absent) and there are no floating-point numbers.
 */
export interface ScanPayload {
  scan_id: Uuid;
  round_id: Uuid | null;
  checkpoint_id: Uuid | null;
  method: "nfc" | "qr" | "manual";
  /**
   * NFC tag UID: uppercase hex without separators, 4 to 10 bytes.
   */
  tag_uid: string | null;
  /**
   * The scanned QR text. Only waypost:cp: codes are accepted by the reader; an unknown one is still recorded (unknown_tag).
   */
  qr_payload: string | null;
  /**
   * Raw NDEF message of the tag, if any; kept for later verification (e.g. NTAG 424 DNA).
   */
  ndef_raw: Base64 | null;
  lat_e7: LatE7 | null;
  lng_e7: LngE7 | null;
  accuracy_dm: AccuracyDm | null;
  is_mock: boolean;
  flags: ("manual" | "out_of_order" | "out_of_round" | "unknown_tag" | "mock_location")[];
  /**
   * Free text from the guard (Hungarian).
   */
  note: string | null;
  /**
   * Photos taken with the camera, each with the SHA-256 of the uploaded file, so a replaced photo is detected.
   *
   * @maxItems 5
   */
  media: {
    id: Uuid;
    sha256: Hash;
  }[];
}

